module logic;
use model {Span,Summary};
use util {reverse};
record Cursor {pending:List<Span>,kept:List<Span>,current:Span,active:Bool,points:I64,rejected:I64}
fn run(spans:List<Span>)->Summary {
 let final=fold(i in List::length(spans),cursor:Cursor=Cursor {pending:spans,kept:List::empty<Span>(),current:Span {start:0,end:0},active:false,points:0,rejected:0}) {
  let item=List::head(cursor.pending);
  if item.end<item.start {Cursor {...cursor,pending:List::tail(cursor.pending),rejected:cursor.rejected+1}} else {
   if !cursor.active {
    Cursor {...cursor,pending:List::tail(cursor.pending),current:item,active:true}
   } else {
    if item.start<=cursor.current.end+1 {
     let mergedEnd=if item.end>cursor.current.end {item.end} else {cursor.current.end};
     Cursor {...cursor,pending:List::tail(cursor.pending),current:Span {start:cursor.current.start,end:mergedEnd}}
    } else {
     Cursor {...cursor,pending:List::tail(cursor.pending),kept:List::prepend(cursor.current,cursor.kept),current:item,points:cursor.points+cursor.current.end-cursor.current.start+1}
    }
   }
  }
 };
 let output=if final.active {List::prepend(final.current,final.kept)} else {final.kept};
 let totalPoints=if final.active {final.points+final.current.end-final.current.start+1} else {final.points};
 Summary {spans:reverse(output),points:totalPoints,rejected:final.rejected}
}

